SourceCode.Declaration:
/// <summary>
/// Helper class used to carry item inquiry filter values between forms/parts.
/// Holds an ItemId and an InventLocationId and provides simple parm methods
/// and a construct factory to create an instance with initial values.
/// </summary>
internal final class METItemInquiryHelper
{
    ItemId itemId;
    InventLocationId inventLocationId;

}

Method.Source:
/// <summary>
/// Gets or sets the ItemId filter value.
/// </summary>
/// <param name="_itemid">Optional ItemId to set. If omitted, the current value is returned.</param>
/// <returns>The current ItemId value stored in the helper.</returns>
public ItemId parmItemId(ItemId _itemid = itemId)
{
    itemId = _itemid;
    return itemId;
}

/// <summary>
/// Gets or sets the InventLocationId (warehouse) filter value.
/// </summary>
/// <param name="_inventLocationId">Optional InventLocationId to set. If omitted, the current value is returned.</param>
/// <returns>The current InventLocationId value stored in the helper.</returns>
public InventLocationId parmInventLocationId(InventLocationId _inventLocationId = inventLocationId)
{
    inventLocationId = _inventLocationId;
    return inventLocationId;
}

/// <summary>
/// Factory method to create a new METItemInquiryHelper with the given filter values.
/// </summary>
/// <param name="_itemId">ItemId to initialize the helper with (optional).</param>
/// <param name="_inventLocationId">InventLocationId to initialize the helper with (optional).</param>
/// <returns>New instance of METItemInquiryHelper with the supplied values set.</returns>
public static METItemInquiryHelper construct(
    ItemId _itemId = '',
    InventLocationId _inventLocationId = '')
{
    METItemInquiryHelper helper = new METItemInquiryHelper();
    helper.parmItemId(_itemId);
    helper.parmInventLocationId(_inventLocationId);


    return helper;
}
